:host { display: block; height: 100%; min-width: 0; }

.rr-tile {
    width: 100%; height: 100%; box-sizing: border-box; margin: 0; padding: 10px 12px;
    display: flex; flex-direction: column; gap: 6px; text-align: left; font: inherit; font-size: 13px; color: #181818;
    background: #fff; border: 1px solid #e5e5e5; border-radius: 4px; box-shadow: 0 2px 2px rgba(0, 0, 0, 0.05);
    cursor: pointer; min-width: 0;
}
.rr-tile:hover, .rr-tile:focus-visible { border-color: #0176d3; box-shadow: 0 0 0 1px #0176d3; outline: none; }
.rr-tile-flash { animation: rr-flash 2.4s ease-out 1; }
@keyframes rr-flash {
    0%, 40% { border-color: #0176d3; box-shadow: 0 0 0 3px #b0c4df; background: #eef4ff; }
    100% { border-color: #e5e5e5; box-shadow: 0 2px 2px rgba(0, 0, 0, 0.05); background: #fff; }
}
.rr-tile-head { display: flex; align-items: center; gap: 8px; min-width: 0; }
.rr-tile-name { font-size: 14px; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.rr-tile-status { display: inline-flex; align-items: center; gap: 5px; margin-left: auto; font-size: 12px; color: #444; white-space: nowrap; }
.rr-tile-facts { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 3px 10px; font-size: 12px; }
.rr-tile-lab { color: #5c5c5c; }
.rr-tile-val, .rr-mono, .rr-weak { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.rr-mono { font-family: ui-monospace, Menlo, Consolas, monospace; font-size: 12px; }
.rr-weak { color: #5c5c5c; }
.rr-tile-foot {
    display: flex; align-items: center; justify-content: space-between; gap: 8px; margin-top: auto;
    border-top: 1px solid #f3f3f3; padding-top: 6px; font-size: 12px; color: #5c5c5c;
}
.rr-tile-open { color: #0b5cab; white-space: nowrap; }

.rr-pill {
    display: inline-flex; align-items: center; height: 20px; padding: 0 8px; border-radius: 10px;
    font-size: 11px; font-weight: 700; white-space: nowrap; flex: none;
}
.rr-pill-info { background: #eef4ff; color: #014486; }
.rr-pill-none { background: #f3f3f3; color: #444; }

.rr-dot { width: 8px; height: 8px; border-radius: 50%; flex: none; display: inline-block; background: #939393; }
.rr-dot-ok { background: #2e844a; }
.rr-dot-bad { background: #ba0517; }
.rr-dot-wait { background: #dd7a01; }

@media (prefers-reduced-motion: reduce) { .rr-tile-flash { animation: none; border-color: #0176d3; } }
